/*
 * Rail + one central list-or-reader surface + contact context. The contact
 * column exists only at >=1000 CSS px; strictly below it, the rail exposes a
 * keyboard-operable Contact disclosure instead.
 */
.app-main {
  /* Shell body type: everything not on another step of the scale is 12px. */
  font-size: var(--type-body);
  line-height: var(--leading-ui);
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  /* Header, static in-flow notices, the list-or-reader surface, then the
     bottom dock (selection, action outcome, command error); the rail and
     contact pane span all four so the header lives in the list column. */
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  flex: 1;
  min-height: 0;
  position: relative;
}

.app-main > .rail {
  grid-column: 1;
  grid-row: 1 / -1;
}

.app-main > .app-header,
.app-main > .list-notices,
.app-main > .list-dock {
  grid-column: 2;
}

.app-main > .app-header { grid-row: 1; }
