/* UX-04 single-slot action notice: in-flow, never covers rows or reader controls. */
.action-notice {
  display: flex;
  gap: 4px 12px;
  align-items: center;
  flex-wrap: wrap;
  min-height: 36px;
  padding: 6px 0;
}
/* The empty region stays rendered at zero height/padding (never display:none):
   a hidden live region is removed from the accessibility tree and inserted
   content at the moment it becomes rendered may not be announced. */
.action-notice-empty { min-height: 0; padding: 0; }
.action-notice-text { margin: 0; font-size: var(--type-body); display: flex; gap: 2px 12px; flex-wrap: wrap; align-items: baseline; }
.action-notice-label { color: var(--text-primary); font-weight: var(--weight-strong); }
.action-notice-status { color: var(--text-secondary); }
/* Honest state (DESIGN.md Status): pending, unknown and partial are Amber
   Notice; confirmed failures are Coral Fault; settled stays Ash. The words
   always carry the meaning; colour only reinforces it. Ratios on Warm Charcoal
   (#292826): Amber 8.68:1, Coral 7.69:1, Ash 7.79:1 (>=4.9:1 even on Focus Stone). */
.action-notice-status[data-status="pending"],
.action-notice-status[data-status="unknown"],
.action-notice-status[data-status="partial"] { color: var(--warning); }
.action-notice-status[data-status="failed"] { color: var(--danger); }
.action-notice-expired { color: var(--warning); }
.action-notice-undo { display: flex; gap: 2px; align-items: center; }
/* Ghost text actions in the dock bars carry the Title weight. */
.action-notice-undo button,
.selection-actions button { font-weight: var(--weight-strong); }
/* The leading action's label starts on the content inset (its 8px padding
   sits in the gap before it). */
.action-notice-undo { margin-left: -8px; }
.action-notice-undo kbd,
.selection-bar kbd { font: inherit; color: var(--text-secondary); font-variant-numeric: tabular-nums; }
.action-backdrop { position: fixed; inset: 0; z-index: 100; background: var(--overlay-backdrop); display: flex; align-items: flex-start; justify-content: center; padding: 15vh 16px 16px; }
/* Shared modal panel: Lifted Charcoal, 10px radius, Overlay lift. */
.action-overlay { width: min(576px, 100%); max-height: 70vh; overflow: auto; background: var(--surface-raised); color: var(--text-primary); border: 0; border-radius: 10px; padding: 0; box-shadow: var(--overlay-lift); font-size: var(--type-body); line-height: var(--leading-ui); }

.split-editor select { padding: .3rem; }

